mapper.select:
SELECT DISTINCT employee.id, employee.user_id, employee.employee_no, employee.name, employee.employment_status, employee.version FROM t_employee employee INNER JOIN t_user user_account ON user_account.id = employee.user_id AND user_account.account_status = 'ACTIVE' AND user_account.account_enabled = 1 AND user_account.account_no_locked = 1 AND user_account.account_no_expired = 1 AND user_account.credentials_no_expired = 1 AND user_account.manual_locked = 0 AND (user_account.auto_locked_until IS NULL OR user_account.auto_locked_until <= #{effectiveAt}) AND (user_account.account_expires_at IS NULL OR user_account.account_expires_at > #{effectiveAt}) AND (user_account.password_expires_at IS NULL OR user_account.password_expires_at > #{effectiveAt}) INNER JOIN t_employee_assignment assignment ON assignment.employee_id = employee.id AND assignment.assignment_type = 'PRIMARY' AND assignment.status = 'ACTIVE' AND assignment.active_primary_marker = 1 AND assignment.effective_from <= #{effectiveAt} AND (assignment.effective_to IS NULL OR assignment.effective_to > #{effectiveAt}) INNER JOIN t_organization_unit organization_unit ON organization_unit.id = assignment.organization_unit_id AND organization_unit.enabled = 1 AND organization_unit.migration_placeholder = 0 INNER JOIN t_position position ON position.id = assignment.position_id AND position.enabled = 1 AND position.code <> 'UNASSIGNED_POSITION' WHERE employee.employment_status = 'ACTIVE'
AND employee.id <> #{excludedEmployeeId}
AND assignment.organization_unit_id IN
#{organizationUnitId}
ORDER BY employee.employee_no, employee.id

mapper.update:
UPDATE t_employee
SET version = version + 1,
    edit_time = #{editTime},
    edit_by = #{editBy}
WHERE id = #{employeeId}
  AND version = #{expectedVersion}

UPDATE t_employee SET name=#{employee.name},phone=#{employee.phone},email=#{employee.email},
  avatar_url=#{employee.avatarUrl},phone_verified=#{employee.phoneVerified},email_verified=#{employee.emailVerified},
  profile_completed=#{employee.profileCompleted},profile_version=profile_version+1,
  edit_time=#{employee.editTime},edit_by=#{employee.editBy}
WHERE id=#{employee.id} AND profile_version=#{expectedProfileVersion}
